"""Prepare a read-only Canvas inspection, without registering candidate game art."""
from pathlib import Path
import argparse,gzip,json
parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--serve-root',type=Path,default=Path('/tmp/cqc-p40-contact-serve'));args=parser.parse_args()
root=Path(__file__).resolve().parent.parent
review=root/'art/core__snake/mgs3-camo-soviet-woodland/review'
geometry=json.loads(gzip.decompress((review/'SOURCE_GEOMETRY_CANDIDATE_V1.json.gz').read_bytes()))
args.serve_root.mkdir(parents=True,exist_ok=True)
link=args.serve_root/'art'
if link.exists() or link.is_symlink():
 if not link.is_symlink() or link.resolve()!=root/'art':raise SystemExit('Unexpected serve-root art path')
else:link.symlink_to(root/'art',target_is_directory=True)
for source in geometry['sources']:source['url']='/'+str(Path(source['path']).relative_to(root))
html='''<!doctype html><html><head><meta charset="utf-8"><title>P40 candidate inspection — not playable</title><style>body{margin:0;background:#11191d;color:#fff;font:14px sans-serif}canvas{display:block;margin:0}p{margin:8px}</style></head><body><p>Sources candidates : aucune admission dans le jeu. R/L recharge = HOLD. Les anciens cycles de marche restent remplacés uniquement dans cette inspection.</p><canvas id="poses" width="1440" height="2112"></canvas><canvas id="alpha" width="1360" height="510"></canvas><script>
const data=__GEOMETRY__,images=new Map();
const hash=bytes=>crypto.subtle.digest('SHA-256',bytes).then(b=>Array.from(new Uint8Array(b),v=>v.toString(16).padStart(2,'0')).join(''));
async function load(source){const response=await fetch(source.url);if(!response.ok)throw Error('Source HTTP '+response.status);const bytes=await response.arrayBuffer();if(bytes.byteLength!==source.bytes||await hash(bytes)!==source.sha256)throw Error('Source pin mismatch');const image=new Image();const url=URL.createObjectURL(new Blob([bytes],{type:'image/png'}));image.src=url;await image.decode();if(image.naturalWidth!==source.dimensions[0]||image.naturalHeight!==source.dimensions[1])throw Error('Source dimensions differ');images.set(source.path,image);URL.revokeObjectURL(url);}
function drawPose(c,image,pose,x,y,k){const r=pose.rect,p=pose.candidatePivot;c.save();c.translate(x,y);c.scale(k,k);c.beginPath();pose.clipPolygon.forEach((v,i)=>{const a=(v[0]-p[0])*r[2],b=(v[1]-p[1])*r[3];i?c.lineTo(a,b):c.moveTo(a,b);});c.closePath();c.clip();c.drawImage(image,...r,-r[2]*p[0],-r[3]*p[1],r[2],r[3]);c.restore();}
(async()=>{await Promise.all(data.sources.map(load));const canvas=document.querySelector('#poses'),c=canvas.getContext('2d');c.fillStyle='#152128';c.fillRect(0,0,canvas.width,canvas.height);const gait=data.sources[2];const names=['idle','guard','walk-a','walk-b','crouch','jump','punch','low','grab','grenade-release','knife','shoot','reload','hit','ko','roll'];const rendered=[];
for(let faceIndex=0;faceIndex<2;faceIndex++){const side=faceIndex?'left':'right',main=data.sources[faceIndex],standing=main.poses[0].nativeAlphaBounds[3],neutral=gait.poses.find(p=>p.name===side+'-walk-page-neutral');for(let index=0;index<16;index++){const col=index%4,row=Math.floor(index/4)+faceIndex*4,x=col*360,y=row*264;let source=main,pose=main.poses[index],height=standing;if(index===2||index===3){source=gait;pose=gait.poses.find(p=>p.side===side&&p.semanticPoseIndex===index);height=neutral.nativeAlphaBounds[3];}const held=index===12;c.fillStyle=held?'#3e2020':'#152128';c.fillRect(x,y,359,263);c.strokeStyle='#50707e';c.strokeRect(x+.5,y+.5,359,263);c.fillStyle=held?'#ffbbb6':'#d7e4e9';c.fillText(side.toUpperCase()+' '+index+' '+names[index]+(held?' — HOLD':''),x+8,y+18);c.fillStyle='#849ba7';c.font='10px sans-serif';c.fillText('géométrie candidate · aucun état approuvé',x+8,y+32);c.font='14px sans-serif';c.strokeStyle='#61808c';c.beginPath();c.moveTo(x+5,y+243.5);c.lineTo(x+355,y+243.5);c.stroke();const k=180/height,left=180-pose.rect[2]*pose.candidatePivot[0]*k,right=180+pose.rect[2]*(1-pose.candidatePivot[0])*k;if(left<2||right>358)throw Error('Diagnostic cell would hide a native pose');drawPose(c,images.get(source.path),pose,x+180,y+243,k);rendered.push({side,index,sourceSHA256:source.sha256,pose:pose.name,held,sourceHeightCandidate:height,diagnosticFullWidthFitsCell:true});}}
const ac=document.querySelector('#alpha'),a=ac.getContext('2d'),image=images.get(gait.path);const backgrounds=['#00cfd7','#132028'];const samples=[];for(let j=0;j<2;j++){const x=j*680;a.fillStyle=backgrounds[j];a.fillRect(x,0,680,510);a.fillStyle=j?'white':'black';a.font='15px sans-serif';a.fillText('PNG natif sur fond '+backgrounds[j]+' · aucune retouche',x+15,23);a.drawImage(image,x+15,40,645.12,430.08);for(const[xs,ys]of [[0,0],[750,500],[10,500],[500,500],[1535,1023]]){const px=Math.floor(x+15+xs*.42),py=Math.floor(40+ys*.42),rgba=[...a.getImageData(px,py,1,1).data];samples.push({background:backgrounds[j],sourceXY:[xs,ys],canvasXY:[px,py],rgba});}}
const rawCanvas=document.createElement('canvas');rawCanvas.width=image.naturalWidth;rawCanvas.height=image.naturalHeight;const rc=rawCanvas.getContext('2d');rc.drawImage(image,0,0);const nativeSamples=[[0,0],[750,500],[10,500],[500,500],[1535,1023]].map(([x,y])=>({xy:[x,y],rgba:[...rc.getImageData(x,y,1,1).data]}));if(nativeSamples.some(s=>s.rgba[3]!==0))throw Error('Expected transparent interfigure sample differs');
window.__P40_DIAGNOSTIC_RESULT={status:'read-only-candidate-inspection-complete',runtimeAdmitted:false,artApproved:false,actualGameRendererUsed:false,sourcePNGsModified:false,canvasClippingFromExplicitOwnership:true,renderedPoses:rendered.length,heldReloads:rendered.filter(x=>x.held),nativeTransparentSamples:nativeSamples,matteSamples:samples,rendered};document.body.dataset.ready='true';})().catch(error=>{window.__P40_DIAGNOSTIC_RESULT={status:'failed',error:String(error)};document.body.dataset.ready='failed';});
</script></body></html>'''.replace('__GEOMETRY__',json.dumps(geometry,separators=(',',':')))
out=args.serve_root/'candidate-contact-v1.html';out.write_text(html);print(out)
